tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(37.5deg,#ff5500,#0055ff,#00ff55)]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-[37.5deg] from-[#ff5500] via-[#0055ff] to-[#00ff55]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(37.5deg, #ff5500, #0055ff, #00ff55);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(37.5deg, #ff5500, #0055ff, #00ff55);
}

css-variables:
:root {
  --gradient-angle: 37.5deg;
  --gradient-color-1: #ff5500;
  --gradient-color-2: #0055ff;
  --gradient-color-3: #00ff55;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1), var(--gradient-color-2), var(--gradient-color-3));
}

/* Usage: background: var(--gradient); */

